import chalk from 'chalk';
import { isNodeModule } from '../utils.js';
// This directly mirrors the extension list from Vite's `CSS_LANGS_RE` constant, which is not exported from Vite.
// When updating Vite, we will have to check if this list has changed and update it accordingly.
const CSS_EXTENSIONS = new Set([
    '.css',
    '.less',
    '.sass',
    '.scss',
    '.styl',
    '.stylus',
    '.sss',
    '.postcss',
    '.pcss',
]);
const BLOCKED_CSS_MODULE_ID = '\0ui-ext-css-blocked';
/**
 * This is a Vite plugin that blocks CSS imports in UI extensions.
 * In the dev server we warn the user, but allow the extension to build and be served.
 * In remote builds we throw an error so the extension cannot be built.
 *
 * @param args An object containing optional logger and onCssBlocked callback.
 */
const cssBlockingPlugin = ({ logger, onCssBlocked, } = {}) => {
    return {
        name: 'ui-extensions-css-blocking-plugin',
        enforce: 'pre',
        /**
         * resolveId is called for every import statement in the module graph.
         * We use this to check if the import is a CSS file (or preprocessor file) and block it if so.
         */
        resolveId(id, importer) {
            // node_modules imports are blocked silently (below) — the author can't fix them,
            // and letting one through runs the preprocessor package from the customer's tree.
            const importedFromDependency = isNodeModule(importer);
            const cleanId = id.split('?')[0];
            const dotIndex = cleanId.lastIndexOf('.');
            if (dotIndex === -1) {
                return null;
            }
            const ext = cleanId.slice(dotIndex);
            if (CSS_EXTENSIONS.has(ext)) {
                if (!importedFromDependency) {
                    const message = `CSS is not supported. Remove the import of '${id}' from your extension.`;
                    // Local dev should warn, but not error, so the extension can still be served.
                    if (logger) {
                        logger.warn(chalk.yellow(`WARNING: ${message}`));
                    }
                    else {
                        // Remote builds notify the caller via callback so it can throw a clean Error after build() resolves.
                        // Throwing here causes Vite to prepend an internal [plugin-name] attribution to the message.
                        onCssBlocked?.(message);
                    }
                }
                // We return a virtual empty module so Vite doesn't run its own CSS pipeline.
                return BLOCKED_CSS_MODULE_ID;
            }
            // For non-CSS, let Vite handle the import normally.
            return null;
        },
        /**
         * load is called for each module ID that Vite needs to load.
         * Returning '' for the blocked CSS module returns an empty JS module, effectively blocking the CSS import.
         */
        load(id) {
            if (id === BLOCKED_CSS_MODULE_ID) {
                return '';
            }
            return null;
        },
    };
};
export default cssBlockingPlugin;
